from django.http import HttpResponse
from django.test import override_settings

from bloomerp.config.definition import BloomerpConfig
from bloomerp.models.communication.email_account import EmailAccount
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestDisconnectEmailAccountView(BloomerpDetailViewTestCase):
    """Tests function `disconnect_email_account` from `bloomerp/views/communication/disconnect_email_account.py`."""

    view_name = "disconnect_email_account"
    model = EmailAccount

    def prepare_account(self, scenario: RequestScenario) -> None:
        """Create one connected account under the existing encryption setting."""
        self.settings_override = override_settings(
            BLOOMERP_CONFIG=BloomerpConfig(email_secret_key="test-secret")
        )
        self.settings_override.enable()
        self.account = EmailAccount.objects.create(
            email_address="connected@example.com",
            provider="outlook",
            oauth_client_id="client-id",
            oauth_client_secret="client-secret",
            oauth_tenant_id="11111111-1111-1111-1111-111111111111",
            access_token="access-secret",
            refresh_token="refresh-secret",
            status=EmailAccount.Status.ACTIVE,
        )
        scenario.view_kwargs = {"pk": str(self.account.pk)}

    def restore_settings(self, scenario: RequestScenario) -> None:
        """Restore test encryption after the isolated request scenario."""
        self.settings_override.disable()

    def authorization_is_removed(self, response: HttpResponse) -> bool:
        """Verify disconnect removes mailbox tokens and stops receiving."""
        self.account.refresh_from_db()
        return (
            self.account.status == EmailAccount.Status.DRAFT
            and not self.account.sync_enabled
            and not self.account.access_token
            and not self.account.refresh_token
            and self.account.next_sync_at is None
            and bool(self.account.extra_settings.get("authorization_revision"))
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        return [
            RequestScenario(
                name="An authorized account editor can disconnect",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_account,
                cleanup=self.restore_settings,
                expected=ExpectedResult(
                    response_validators=self.authorization_is_removed
                ),
            ),
            RequestScenario(
                name="An account without change access cannot be disconnected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_account,
                cleanup=self.restore_settings,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Disconnect requires POST",
                user=self.admin_user,
                prepare=self.prepare_account,
                cleanup=self.restore_settings,
                expected=ExpectedResult(status_code=405),
            ),
        ]
